CREATE TABLE IF NOT EXISTS business_link (id BINARY(16) PRIMARY KEY, business_id BINARY(16) NOT NULL, name VARCHAR(32) NOT NULL, released_at TIMESTAMP(6) NULL, created_at TIMESTAMP(6) NOT NULL, CONSTRAINT business_link_name_unique UNIQUE (name), INDEX business_link_business_id_released_at (business_id, released_at), INDEX business_link_released_at (released_at), CONSTRAINT fk_business_link_business_id__id FOREIGN KEY (business_id) REFERENCES business(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS business_link_change (id BINARY(16) PRIMARY KEY, business_id BINARY(16) NOT NULL, changed_at TIMESTAMP(6) NOT NULL, INDEX business_link_change_business_id_changed_at (business_id, changed_at), INDEX business_link_change_changed_at (changed_at), CONSTRAINT fk_business_link_change_business_id__id FOREIGN KEY (business_id) REFERENCES business(id) ON DELETE CASCADE ON UPDATE RESTRICT);
ALTER TABLE client ADD COLUMN IF NOT EXISTS phone_index CHAR(44) NULL, ADD COLUMN IF NOT EXISTS created_at TIMESTAMP(6) NULL;
UPDATE client SET created_at = LEAST(last_activity_at, CURRENT_TIMESTAMP(6)) WHERE created_at IS NULL;
ALTER TABLE client MODIFY COLUMN IF EXISTS created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), ADD INDEX IF NOT EXISTS client_business_id_created_at (business_id, created_at), ADD INDEX IF NOT EXISTS client_business_id_phone_index (business_id, phone_index), DROP INDEX IF EXISTS client_business_id_name_index, DROP COLUMN IF EXISTS name_index;
CREATE TABLE IF NOT EXISTS client_name_token (business_id BINARY(16) NOT NULL, token BINARY(16) NOT NULL, client_id BINARY(16) NOT NULL, PRIMARY KEY (business_id, token, client_id), INDEX client_name_token_client_id (client_id), CONSTRAINT fk_client_name_token_client_id__id FOREIGN KEY (client_id) REFERENCES client(id) ON DELETE CASCADE ON UPDATE RESTRICT);
ALTER TABLE client ADD COLUMN IF NOT EXISTS telegram_username_encrypted VARBINARY(256) NULL;
